import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb["Sheet2"]
vws = vals["Sheet2"]

def is_one(value):
    if value is None or isinstance(value, bool):
        return False
    try:
        return float(value) == 1.0
    except (TypeError, ValueError):
        return False

max_row = vws.max_row
answer_row = 15
columns = [2, 3, 4, 5]  # B, C, D, E

results = []
for col in columns:
    run = 0
    total = 0

    for row in range(1, max_row + 1):
        if row == answer_row:
            continue

        if is_one(vws.cell(row=row, column=col).value):
            run += 1
        else:
            if run >= 2:
                total += run
            run = 0

    if run >= 2:
        total += run

    ws.cell(row=answer_row, column=col).value = total
    results.append(total)

print("Computed totals B15:E15:", results)
wb.save(OUT)
